CREATE TABLE IF NOT EXISTS "Source" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL,
	"baseUrl" TEXT NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "SearchQuery" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"sourceId" INTEGER,
	"targetUrl" TEXT,
	"lastDigestSentAt " TIMESTAMPTZ,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "Record" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"doi" TEXT NOT NULL UNIQUE,
	"title" TEXT NOT NULL,
	"description" TEXT,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "User" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"name" TEXT NOT NULL,
	"userName" TEXT NOT NULL,
	"email" TEXT NOT NULL,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "UserSearchQuery" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"userId" INTEGER NOT NULL,
	"searchQueryId" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "SourceRecord" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"recordId" INTEGER,
	"sourceId" INTEGER,
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "SearchQueryRecord" (
	"searchQueryId" INTEGER UNIQUE,
	"recordId" INTEGER UNIQUE,
	"firstSeenAt" TIMESTAMPTZ,
	PRIMARY KEY("searchQueryId", "recordId")
);

ALTER TABLE "UserSearchQuery"
ADD FOREIGN KEY("userId") REFERENCES "User"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "SearchQuery"
ADD FOREIGN KEY("id") REFERENCES "UserSearchQuery"("searchQueryId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "SearchQuery"
ADD FOREIGN KEY("sourceId") REFERENCES "Source"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "Source"
ADD FOREIGN KEY("id") REFERENCES "SourceRecord"("sourceId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "Record"
ADD FOREIGN KEY("id") REFERENCES "SourceRecord"("recordId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "SearchQuery"
ADD FOREIGN KEY("id") REFERENCES "SearchQueryRecord"("searchQueryId")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "SearchQueryRecord"
ADD FOREIGN KEY("recordId") REFERENCES "Record"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;